// Spec 0014 GNR-8, GNR-9: what a target writes, and the one place files reach the disk.
import { mkdirSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import type { Model } from "./model.ts";

/** One generated file, its path relative to the SDK repo root. */
export interface OutputFile {
  path: string;
  content: string;
}

/** Facts every generated file header names (GNR-8). */
export interface Provenance {
  /** The orvano commit the generator ran from, 40 hex. */
  commit: string;
  version: string;
  contractSha256: string;
}

export function provenance(model: Model, commit: string): Provenance {
  return { commit, version: model.version, contractSha256: model.contractSha256 };
}

/** The header line every generated file carries, after the language's generated marker. */
export function headerLine(source: Provenance): string {
  return `Generated by @orvano/sdk-generator ${source.commit} from contract ${source.version} (sha256 ${source.contractSha256.slice(0, 12)}). Do not edit.`;
}

/** What a target owns in its repo: deleted and rewritten on every run, and nothing else is touched. */
export interface Ownership {
  directories: string[];
  files: string[];
}

export function writeOutput(root: string, ownership: Ownership, files: OutputFile[]): void {
  for (const directory of ownership.directories)
    rmSync(join(root, directory), { recursive: true, force: true });
  for (const file of ownership.files) rmSync(join(root, file), { force: true });
  for (const file of files) {
    if (!isOwned(ownership, file.path))
      throw new Error(`The generator tried to write ${file.path}, which its target does not own.`);
    const path = join(root, file.path);
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, file.content);
  }
}

function isOwned(ownership: Ownership, path: string): boolean {
  return (
    ownership.files.includes(path) ||
    ownership.directories.some((directory) => path.startsWith(`${directory}/`))
  );
}
